  {name=perf,column=2,between=row6 and row14}
{
\begin{center}
\renewcommand{\arraystretch}{1.25}
\setlength{\tabcolsep}{10pt}
{\fontsize{30}{38}\selectfont
\rowcolors{2}{accent!10}{white}
\begin{tabular}{lcc}
\rowcolor{accent!18}
\textbf{Domain} & \textbf{AI Sens.} & \textbf{Clin. Sens.}\\
Radiology & 89.3\% & 79.8\%\\
Dermatology & 86.7\% & 76.5\%\\
Ophthalmology & 90.1\% & 82.3\%\\
Pathology & 84.0\% & 74.1\%\\
\end{tabular}}
\end{center}
\vspace{2mm}
\colorbox{primary!20}{\parbox{0.95\linewidth}{\textbf{Headline:} Median AI sensitivity \textbf{87.5\%} vs clinician-only \textbf{78.2\%}.}}
\vspace{2mm}
\begin{itemize}
  \item Specificity gains smaller (93.1\% vs 91.4\%).
  \item Largest improvements in imaging-heavy pathways.
\end{itemize}
}

\posterbox[darkcard,title={Paired Comparison (Sensitivity)}]
  {name=bars,column=2,between=row14 and bottom}
{
\begin{center}
\begin{tcolorbox}[enhanced,arc=0pt,boxrule=0pt,colback=white,
  left=14pt,right=14pt,top=12pt,bottom=12pt]

% Simple paired bars using tikz (pgf) without external data
\begingroup
\setlength{\fboxsep}{0pt}
\newcommand{\bar}[3]{%
  \textcolor{#1}{\rule{#2\linewidth}{18pt}}\hspace{6pt}{\fontsize{30}{36}\selectfont\bfseries #3}}

\RaggedRight
{\fontsize{34}{42}\selectfont\bfseries Clinician-only}\vspace{3mm}\\
\bar{secondary}{0.782}{78.2\%}\\[8mm]
{\fontsize{34}{42}\selectfont\bfseries AI-assisted}\vspace{3mm}\\
\bar{accent}{0.875}{87.5\%}
\endgroup

\end{tcolorbox}
\end{center}
\vspace{2mm}
{\fontsize{28}{34}\selectfont\color{textgray}
Paired comparison emphasises sensitivity lift with AI assistance.}
}

% --- Column 3 ---
\posterbox[redcard,title={Safety, Bias, and Health Equity}]
  {name=safety,column=3,between=row6 and row12}
{
\begin{itemize}
  \item \textbf{18\%} report demographic bias assessment.
  \item Documented gaps: \textbf{5--12 pp} sensitivity drops.
  \item Safety events rare in trials; under-reporting likely.
\end{itemize}
\vspace{2mm}
\colorbox{gold!20}{\parbox{0.95\linewidth}{\textbf{Warning:} Lack of bias auditing limits confidence in equity and safety.}}
}

\posterbox[highlightcard,title={The Translational Implementation Gap}]
  {name=gap,column=3,between=row12 and row18}
{
\begin{center}
{\fontsize{120}{132}\selectfont\bfseries\color{white} <5\%}\\[-2mm]
{\fontsize{34}{42}\selectfont\color{white!92} published models prospectively validated}
\end{center}
\vspace{2mm}
\begin{itemize}
  \item Data infrastructure and interoperability gaps.
  \item Evolving regulation; unclear lifecycle updates.
  \item Trust, explainability, workflow alignment.
  \item Limited cost-effectiveness evidence.
\end{itemize}
}

\posterbox[bluecard,title={What Needs to Change (System View)}]
  {name=system,column=3,between=row18 and bottom}
{
\begin{itemize}
  \item Prospective trials as a default expectation.
  \item Audit, monitor, and report performance drift.
  \item Align incentives for safe deployment.
\end{itemize}
}

\end{tcbposter}
\end{document}
